/**
 * A picture opened large over the page (`design/components/lightbox.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/lightbox.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, createUniqueId, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'
import { Portal } from 'solid-js/web'

import * as zag from '@zag-js/dialog'
import { normalizeProps } from '@zag-js/solid'

import {
  Each,
  afresh,
  agentMember,
  claimSlot,
  createCell,
  createDerived,
  elementRef,
  mergeParts,
  modalFocusTarget,
  resolveSlot,
  scope,
  useDirection,
  useMachine,
  watchEffect,
  type Defaults,
} from '@polymorph/solid'
import { usePresence } from '@polymorph/solid/motion'
import styles from '@polymorph/recipes/overlays/lightbox.module.css'
import Button from '../controls/Button'
import Image from '../structure/Image'

export interface LightboxImage {
  src: string
  alt: string
}

export interface LightboxMessages {
  close: string
  previous: string
  next: string
  position: (position: number, count: number) => string
}

export interface LightboxProps {
  /**
   * The picture shown first while the lightbox holds the position. Defaults to 0.
   */
  defaultIndex?: number
  defaultOpen?: boolean
  /**
   * The pictures in reading order. An empty list opens nothing.
   */
  images: LightboxImage[]
  /**
   * The picture shown, counted from 0. Controlled, as in Carousel.
   */
  index?: number
  /**
   * The dialog's accessible name, such as "Attachment preview". It is not drawn.
   */
  label: string
  /**
   * Omit for the English defaults; localized hosts pass their own.
   */
  messages?: LightboxMessages
  /**
   * Called with the index of the picture the reader moved to.
   */
  onIndexChange?: (index: number) => void
  onOpenChange?: (open: boolean) => void
  open?: boolean
  /**
   * A governed control, usually a Button, cloned to receive `onClick`, which also tells the
   * panel where it was opened from. As in Dialog.
   */
  trigger?: JSX.Element
}

/** A picture opened large over the page. */
export default function Lightbox(given: LightboxProps): JSX.Element {
  const props = mergeProps(
    {
      defaultIndex: 0,
      messages: (() => ({
        close: 'Close',
        previous: 'Previous picture',
        next: 'Next picture',
        position: (position, count) => `${position} of ${count}`,
      }))(),
    } as Defaults<LightboxProps, 'defaultIndex' | 'messages'>,
    claimSlot(given),
  )
  return scope(() => {
    const uid = createUniqueId()
    const panel = elementRef<HTMLElement>()
    const scrim = elementRef<HTMLElement>()
    const triggerSlot = resolveSlot(
      () => props.trigger,
      () => ({ onClick: openFrom.value }),
    )
    const opener = createCell(null as HTMLElement | null)
    const mirror = createCell(props.defaultIndex)
    const within = createDerived(
      () => (at: number) => Math.min(Math.max(at, 0), Math.max(props.images.length - 1, 0)),
    )
    const shown = createDerived(() => within.value(props.index ?? mirror.value))
    const several = createDerived(() => props.images.length > 1)
    const current = createDerived(() => props.images.slice(shown.value, shown.value + 1))
    const travel = createDerived(() => (to: number) => {
      if (to < 0 || to >= props.images.length || to === shown.value) return
      mirror.value = to
      props.onIndexChange?.(to)
    })
    const keyDown = createDerived(() => (event: KeyboardEvent) => {
      if (!several.value || event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return
      const rtl = getComputedStyle(event.currentTarget as HTMLElement).direction === 'rtl'
      const forward = rtl ? 'ArrowLeft' : 'ArrowRight'
      const back = rtl ? 'ArrowRight' : 'ArrowLeft'
      if (event.key !== forward && event.key !== back) return
      event.preventDefault()
      travel.value(event.key === forward ? shown.value + 1 : shown.value - 1)
    })
    const focusAfterMove = createDerived(() => () => {
      if (panel.value === null) return
      const previous = panel.value.querySelector<HTMLButtonElement>(
        '[data-lightbox-part="previous"] button',
      )
      const next = panel.value.querySelector<HTMLButtonElement>(
        '[data-lightbox-part="next"] button',
      )
      const active = document.activeElement
      const lost =
        active === null ||
        active === document.body ||
        ((active === previous || active === next) && (active as HTMLButtonElement).disabled)
      if (!lost) return
      const other = [previous, next].find((button) => button !== null && !button.disabled)
      other?.focus()
    })
    const documentDirection = useDirection()
    const service = useMachine(
      zag.machine,
      () =>
        ({
          id: uid,
          dir: documentDirection(),
          open: props.open === undefined ? undefined : props.open && props.images.length > 0,
          defaultOpen:
            props.defaultOpen === undefined
              ? undefined
              : props.defaultOpen && props.images.length > 0,
          initialFocusEl: () => modalFocusTarget(panel.value, 'primary'),
          finalFocusEl: () => opener.value,
          onOpenChange: (details) => {
            props.onOpenChange?.(details.open)
          },
        }) as Partial<zag.Props>,
    )
    const api = createDerived(() => zag.connect(service, normalizeProps))
    const openFrom = createDerived(() => (event?: Event) => {
      if (props.images.length === 0) return
      if (event?.currentTarget instanceof HTMLElement) opener.value = event.currentTarget
      api.value.setOpen(true)
    })
    const scrimPresent = usePresence(
      () => api.value.open,
      () => scrim.value,
      'dialog.scrim',
    )
    const panelPresent = usePresence(
      () => api.value.open,
      () => panel.value,
      'dialog.panel',
    )
    const effect1 = () => {
      focusAfterMove.value()
    }
    watchEffect(
      createMemo(() => shown.value),
      effect1,
      false,
    )
    let release2: (() => void) | undefined
    const effect2 = () => {
      release2?.()
      const ran = agentMember({
        member: 'Lightbox',
        element: () => panel.value,
        state: () => ({
          open: api.value.open,
          index: shown.value,
          images: props.images.map((image) => ({ alt: image.alt })),
        }),
        actions: {
          close: () => api.value.open && api.value.setOpen(false),
          next: () =>
            (() => {
              if (!api.value.open) throw new Error('The lightbox is closed.')
              if (shown.value === props.images.length - 1)
                throw new Error('This is the last picture.')
              travel.value(shown.value + 1)
            })(),
          previous: () =>
            (() => {
              if (!api.value.open) throw new Error('The lightbox is closed.')
              if (shown.value === 0) throw new Error('This is the first picture.')
              travel.value(shown.value - 1)
            })(),
        },
        withholds: () => panel.value,
      })
      release2 = () => {
        ran()
      }
    }
    onMount(effect2)
    onCleanup(() => release2?.())
    return (
      <>
        {triggerSlot()}
        <Portal>
          {afresh(() => (
            <>
              {scrimPresent() ? (
                <div
                  {...mergeParts(api.value.getBackdropProps(), {
                    class: styles.scrim,
                    hidden: undefined,
                    onclick: () => api.value.setOpen(false),
                  })}
                  ref={scrim.attach}
                />
              ) : null}
              {panelPresent() ? (
                <div {...mergeParts(api.value.getPositionerProps(), { class: styles.positioner })}>
                  {/* panel */}
                  <div
                    {...mergeParts(api.value.getContentProps(), {
                      class: styles.panel,
                      hidden: undefined,
                      'data-member': 'lightbox',
                      onkeydown: ($event: KeyboardEvent) => keyDown.value($event),
                    })}
                    ref={panel.attach}
                  >
                    {/* title */}
                    <h2 {...mergeParts(api.value.getTitleProps(), { class: styles.title })}>
                      {props.label}
                    </h2>
                    {/* stage */}
                    <div class={styles.stage}>
                      <Each of={current.value} by={() => shown.value} renew>
                        {(picture) => <Image src={picture.src} alt={picture.alt} loading="eager" />}
                      </Each>
                    </div>
                    {several.value ? (
                      <>
                        {/* previous */}
                        <div class={styles.previous} data-lightbox-part="previous">
                          <Button
                            variant="ghost"
                            tone="neutral"
                            size="sm"
                            iconOnly={true}
                            icon="previous"
                            label={props.messages.previous}
                            disabled={shown.value === 0}
                            onClick={() => travel.value(shown.value - 1)}
                          />
                        </div>
                        {/* next */}
                        <div class={styles.next} data-lightbox-part="next">
                          <Button
                            variant="ghost"
                            tone="neutral"
                            size="sm"
                            iconOnly={true}
                            icon="next"
                            label={props.messages.next}
                            disabled={shown.value === props.images.length - 1}
                            onClick={() => travel.value(shown.value + 1)}
                          />
                        </div>
                        {/* position */}
                        <p class={styles.position} role="status">
                          {props.messages.position(shown.value + 1, props.images.length)}
                        </p>
                      </>
                    ) : null}
                    {/* close */}
                    <div class={styles.close} data-dialog-part="close">
                      <Button
                        variant="ghost"
                        tone="neutral"
                        size="sm"
                        iconOnly={true}
                        icon="close"
                        label={props.messages.close}
                        onClick={() => api.value.setOpen(false)}
                      />
                    </div>
                  </div>
                </div>
              ) : null}
            </>
          ))}
        </Portal>
      </>
    )
  })
}
